function accountsMerge(accounts) {
  const graph = new Map();                    // email -> emails it is linked to
  const name = new Map();                     // email -> owner's name
  const link = (a, b) => {
    if (!graph.has(a)) graph.set(a, []);
    graph.get(a).push(b);
  };
  for (const [owner, ...emails] of accounts) {
    for (const email of emails) {
      name.set(email, owner);
      link(email, emails[0]);                 // join every email to the account's first one
      link(emails[0], email);
    }
  }
  const seen = new Set();
  const result = [];
  for (const start of graph.keys()) {
    if (seen.has(start)) continue;
    const group = [];                         // one connected piece = one person
    const stack = [start];
    seen.add(start);
    while (stack.length > 0) {
      const email = stack.pop();
      group.push(email);
      for (const next of graph.get(email)) {
        if (!seen.has(next)) {
          seen.add(next);
          stack.push(next);
        }
      }
    }
    result.push([name.get(start), ...group.sort()]);
  }
  return result;
}

from collections import defaultdict

def accounts_merge(accounts):
    graph = defaultdict(list)             # email -> emails it is linked to
    name = {}                             # email -> owner's name
    for owner, *emails in accounts:
        for email in emails:
            name[email] = owner
            graph[email].append(emails[0])    # join every email to the account's first one
            graph[emails[0]].append(email)
    seen = set()
    result = []
    for start in graph:
        if start in seen:
            continue
        group = []                        # one connected piece = one person
        stack = [start]
        seen.add(start)
        while stack:
            email = stack.pop()
            group.append(email)
            for nxt in graph[email]:
                if nxt not in seen:
                    seen.add(nxt)
                    stack.append(nxt)
        result.append([name[start]] + sorted(group))
    return result

