vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
    unordered_map<string, vector<string>> graph;         // email -> emails it is linked to
    unordered_map<string, string> name;                  // email -> owner's name
    for (auto& account : accounts) {
        const string& first = account[1];
        for (size_t i = 1; i < account.size(); i++) {
            name[account[i]] = account[0];
            graph[account[i]].push_back(first);          // join every email to the account's first one
            graph[first].push_back(account[i]);
        }
    }
    unordered_set<string> seen;
    vector<vector<string>> result;
    for (auto& entry : graph) {
        const string& start = entry.first;
        if (!seen.insert(start).second) continue;
        vector<string> group;                            // one connected piece = one person
        vector<string> stack = {start};
        while (!stack.empty()) {
            string email = stack.back(); stack.pop_back();
            group.push_back(email);
            for (auto& next : graph[email]) {
                if (seen.insert(next).second) stack.push_back(next);
            }
        }
        sort(group.begin(), group.end());
        group.insert(group.begin(), name[start]);
        result.push_back(group);
    }
    return result;
}

function accountsMerge(accounts) {
  const parent = accounts.map((_, i) => i);   // one group per account to start
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];          // path halving
      x = parent[x];
    }
    return x;
  };
  const owner = new Map();                    // email -> first account that listed it
  accounts.forEach((account, i) => {
    for (const email of account.slice(1)) {
      if (owner.has(email)) parent[find(i)] = find(owner.get(email));   // shared email: same person
      else owner.set(email, i);
    }
  });
  const groups = new Map();                   // root account -> all of its emails
  for (const [email, i] of owner) {
    const root = find(i);
    if (!groups.has(root)) groups.set(root, []);
    groups.get(root).push(email);
  }
  return [...groups].map(([root, emails]) => [accounts[root][0], ...emails.sort()]);
}

def accounts_merge(accounts):
    parent = list(range(len(accounts)))   # one group per account to start

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]] # path halving
            x = parent[x]
        return x

    owner = {}                            # email -> first account that listed it
    for i, account in enumerate(accounts):
        for email in account[1:]:
            if email in owner:
                parent[find(i)] = find(owner[email])   # shared email: same person
            else:
                owner[email] = i
    groups = {}                           # root account -> all of its emails
    for email, i in owner.items():
        groups.setdefault(find(i), []).append(email)
    return [[accounts[root][0]] + sorted(emails) for root, emails in groups.items()]

