    int n = accounts.size();
    parent = new int[n];
    for (int i = 0; i < n; i++) parent[i] = i;          // one group per account to start
    Map<String, Integer> owner = new HashMap<>();        // email -> first account that listed it
    for (int i = 0; i < n; i++) {
        List<String> account = accounts.get(i);
        for (String email : account.subList(1, account.size())) {
            Integer k = owner.putIfAbsent(email, i);
            if (k != null) parent[find(i)] = find(k);    // shared email: same person
        }
    }
    Map<Integer, List<String>> groups = new HashMap<>(); // root account -> all of its emails
    for (Map.Entry<String, Integer> e : owner.entrySet()) {
        groups.computeIfAbsent(find(e.getValue()), k -> new ArrayList<>()).add(e.getKey());
    }
    List<List<String>> result = new ArrayList<>();
    for (Map.Entry<Integer, List<String>> g : groups.entrySet()) {
        List<String> emails = g.getValue();
        Collections.sort(emails);
        emails.add(0, accounts.get(g.getKey()).get(0));
        result.add(emails);
    }
    return result;
}

