}

vector<vector<string>> accountsMerge(vector<vector<string>>& accounts) {
    int n = accounts.size();
    vector<int> parent(n);
    iota(parent.begin(), parent.end(), 0);              // one group per account to start
    auto find = [&](int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];               // path halving
            x = parent[x];
        }
        return x;
    };
    unordered_map<string, int> owner;                    // email -> first account that listed it
    for (int i = 0; i < n; i++) {
        for (size_t j = 1; j < accounts[i].size(); j++) {
            auto [it, isNew] = owner.try_emplace(accounts[i][j], i);
            if (!isNew) {
                int a = find(i), b = find(it->second);
                parent[a] = b;                           // shared email: same person
            }
        }
    }
    unordered_map<int, vector<string>> groups;           // root account -> all of its emails
    for (auto& [email, i] : owner) groups[find(i)].push_back(email);
    vector<vector<string>> result;
    for (auto& [root, emails] : groups) {
        sort(emails.begin(), emails.end());
        emails.insert(emails.begin(), accounts[root][0]);
        result.push_back(emails);
    }
    return result;
}
